def p(url,kind='Official / promotional',label='Product photo',source=None):
    return {'url':url,'type':kind,'label':label,'source':source or url}

def seq(pattern, nums, kind='Promotional / product',source=None):
    return [p(pattern.format(n=n),kind,f'View {i+1}',source) for i,n in enumerate(nums)]

