# Avoid linking an HTML page directly as an image. It is always an offsite reference instead.
for item in RAW + OWNED:
    item.setdefault('rank',None);item.setdefault('status','Wishlist')
    item.setdefault('score',None);item.setdefault('priceMin',None)
    item.setdefault('pros',[]);item.setdefault('cons',[])
    item.setdefault('theme','crimson');item.setdefault('pilot','')
    item.setdefault('reviews',[]);item.setdefault('photos',[])
    item['photos']=[v for v in item['photos'] if re.search(r'\.(png|webp|jpg|jpeg)(\?|$)',v['url'],re.I) or '/file/' in v['url']]

# JSON is the canonical editable catalog. On first build, write the starter dataset;
# on later builds, load edits from data/models.json before rendering pages.
CATALOG = ROOT / 'data' / 'models.json'
CATALOG.parent.mkdir(exist_ok=True)
if CATALOG.exists():
    saved=json.loads(CATALOG.read_text(encoding='utf-8'))
    RAW=saved['wishlist'];OWNED=saved['collection']
else:
    saved={'wishlist':RAW,'collection':OWNED,'updated':'2026-10-30','priceNote':'Indicative Taiwan listing prices from earlier research, not live quotations. Some prices may be outdated.'}
    CATALOG.write_text(json.dumps(saved,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
payload={'wishlist':RAW,'collection':OWNED,'updated':saved.get('updated','2026-10-30'), 'priceNote':saved.get('priceNote','Indicative Taiwan prices, not live quotations.')}
(ROOT/'assets'/'data.js').write_text('window.GUNPLA_DATA = '+json.dumps(payload,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')

HEAD='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#111316"><meta name="description" content="{description}"><title>{title}</title><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Noto+Sans+TC:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{base}assets/style.css"></head><body data-page="{page}" data-base="{base}" data-slug="{slug}"><div id="app"></div><script src="{base}assets/data.js"></script><script defer src="{base}assets/app.js"></script></body></html>'''

def page(filepath, title, description, pageName, base, slug=''):
    filepath.parent.mkdir(parents=True,exist_ok=True)
    filepath.write_text(HEAD.format(title=html.escape(title),description=html.escape(description,quote=True),page=pageName,base=base,slug=slug),encoding='utf8')
page(ROOT/'index.html','Wishlist — Gunpla Hangar','A curated Gunpla wishlist with reviews, straight-build assessments and collection tracking.','wishlist','','')
page(ROOT/'collection'/'index.html','My Collection — Gunpla Hangar','Gunpla model collection and preorder records.','collection','../','')
page(ROOT/'about'/'index.html','About — Gunpla Hangar','Ranking criteria and photo attribution information.','about','../','')
for it in RAW+OWNED:
    page(ROOT/'models'/it['slug']/'index.html',it['full']+' — Gunpla Hangar',it['summary'],'model','../../',it['slug'])
print('Created',len(RAW),'wishlist +',len(OWNED),'collection pages')
